//App es el objeto React

import ItemDetailContainer from "./components/ItemDetailContainer/ItemDetailContainer"
import ItemListContainer from "./components/ItemListContainer/ItemListContainer"
import Cart from "./components/Cart/Cart"
import Order from "./components/Order/Order"
import NavBar from "./components/NavBar/NavBar"
import Footer from "./components/Footer/Footer"
import ComoComprar from "./ComoComprar"
import QuienesSomos from "./QuienesSomos"
import Contacto from "./Contacto"
import { BrowserRouter, Routes, Route} from "react-router-dom"
import React from "react"
import CartContext from "./components/CartContext/CartContext"
import "../src/styles/Styles.scss"
import Asesoramiento from "./Asesoramiento"
import Capacitacion from "./Capacitacion"
import PComerciales from "./PComerciales"


const App = ()=>{
    return(
        <BrowserRouter>
            <CartContext>
                    <NavBar />
                <main>
                    <Routes>
                        <Route exact path="/"  element={<ItemListContainer />}></Route>
                        <Route exact path="/productos/:id" element={<ItemListContainer/>} ></Route>
                        <Route exact path="/Item/:id" element={<ItemDetailContainer />}> </Route>
                        <Route exact path="/Cart" element={<Cart />}> </Route>
                        <Route exact path="/Order" element={<Order />}></Route>
                        <Route exact path="/quienesSomos" element={<QuienesSomos />}></Route>
                        <Route exact path="/asesoramiento" element={<Asesoramiento />}></Route>
                        <Route exact path="/propuestas_comerciales" element={<PComerciales />}></Route>
                        <Route exact path="/capacitacion" element={<Capacitacion />}></Route>
                        <Route exact path="/comoComprar" element={<ComoComprar />}></Route>
                        <Route exact path="/contacto" element={<Contacto />}></Route>
                    </Routes>
                </main>
                <footer>
                    <Footer />
                </footer>
            </CartContext>
        </BrowserRouter>
    );
}

export default App